NAMES={'24bottle':'24Bottles','40weft':'40WEFT','date':'D.A.T.E.','g-star':'G-Star RAW','fk':'F**K','ds2':'DS2','dsquared2':'Dsquared2','jack-jones':'Jack & Jones','jjxx':'JJXX','jj-rebel':'JJ Rebel','levis':"Levi's",'dr-martens':'Dr. Martens','lyle--scott-1874':'Lyle & Scott','mason-s':"Mason's",'jeordie-s':"Jeordie's",'gassa-d-amante':"Gassa d'Amante",'ea7':'EA7','sun68':'SUN68','bob-company':'BOB','atpco':'AT.P.CO','web-cup-capsule-collection':'WEB CUP Capsule','imp-made-for-pleasure':'IMP','reebok-ltd':'Reebok LTD','pro-keds':'Pro-Keds','saint-barth':'MC2 Saint Barth','valsport-1920':'Valsport 1920','philippe-model-paris':'Philippe Model','hey-dude':'HEYDUDE','diesel-time-frames':'Diesel Time Frames','only-play':'Only Play','guess-jeans':'Guess Jeans','gas-jeans':'GAS'}
def nm(slug):
    s=slug.split('_',1)[1]
    return NAMES.get(s, ' '.join(w.capitalize() for w in s.split('-')))
def build(lst,site,logobase):
    out=[]
    for slug,logo in lst:
        if logo and logo.startswith('/'): logo=None if 'nofoto' in logo else logobase+logo
        out.append({"n":nm(slug),"u":f"{site}/it/{slug}/","l":logo})
    return sorted(out,key=lambda x:x['n'].lower())
